INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (29,'2025-2600-0941','Alonso Ovalle','Operación Sede','Operación Sede','Renovación de  computadores para los laboratorios AO3 3304 y 3405',' Este proyecto tiene como objetivo renovar los computadores de los laboratorios AO3 3304, 3405 y 3407, utilizados por las escuelas de Diseño e Informática.  La renovación de estos equipos es esencial para asegurar el soporte adecuado de las herramientas tecnológicas que requieren los estudiantes y docentes.','','Renovación','Equipamiento','PC + Tarjeta de Video',68,'',40003482,2170012600,61070000,62790520,'DGSD','Operacional','Resolución','MARZO',0,0,62790520,0,0,0,0,0,0,0,0,-5904222);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (37,'2025-2600-0942','Alonso Ovalle','Operación Sede','Operación Sede','Renovación de Mobiliario de Punto Estudiantil','Tiene como objetivo la adquisición de mobiliario moderno y funcional para optimizar los espacios destinados al bienestar y convivencia de los alumnos. Estas áreas comunes permiten a los estudiantes compartir momentos de relajación, socialización y descanso fuera del entorno académico formal.','','Renovación','Mobiliario','Mesas',1,'',30012659,2121032600,61070000,991187,'SEDE','Operacional','Resolución','ABRIL',0,0,0,991187,0,0,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (38,'2025-2600-0943','Alonso Ovalle','Operación Sede','Operación Sede','Adquisición de equipamiento para Actividades Estudiantiles','Este proyecto tiene como objetivo la compra de una carpa tipo iglú, destinada a diversas actividades organizadas por el Punto Estudiantil. La carpa será utilizada en eventos que se realicen en el patio AO4 y en los halls AO1 y AO2. Su fácil instalación y versatilidad permitirá a los alumnos disfrutar de un espacio cubierto durante actividades al aire libre, ferias y eventos institucionales, proporcionando un ambiente cómodo y protegido.','','Adquisición','Equipamiento','Carpa tipo Iglú',1,'',30012660,2170012600,61070000,1535100,'SEDE','Operacional','Resolución','ABRIL',0,0,0,1535100,0,0,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (41,'2025-2600-0944','Alonso Ovalle','Operación Sede','Operación Sede','Adquisición de equipamiento para Auditorio AO4','iene como objetivo la compra de una cortina de terciopelo negro para el backstage del Auditorio AO4. La cortina proporcionará un adecuado aislamiento visual y privacidad durante los eventos, especialmente en situaciones donde no sea posible cerrar las puertas del backstage. Con esta Adquisición, se mejorarán las condiciones técnicas del auditorio, garantizando un ambiente más profesional y funcional para las presentaciones y actividades que se lleven a cabo.','','Adquisición','Equipamiento','Cortina terciopelo',1,'',30012661,2170012600,61070000,1000000,'SEDE','Operacional','Resolución','ABRIL',0,0,0,1000000,0,0,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (42,'2025-2600-0945','Alonso Ovalle','Operación Sede','Operación Sede','Adquisición de Equipamiento Audiovisual para eventos de extensión y comunicación','iene como objetivo mejorar la calidad de la producción audiovisual mediante la Adquisición de un micrófono Rode y un trípode Manfrotto, ambos diseñados para su uso con iPhone. El micrófono Rode garantizará una captura de audio clara y profesional en la creación de videos institucionales, mientras que el trípode Manfrotto proporcionará estabilidad y versatilidad durante la filmación. Este equipamiento permitirá optimizar la producción de contenidos, facilitando la creación de videos de alta calidad para campañas de admisión, eventos de extensión y comunicación institucional.','','Adquisición','Equipamiento','Trrípode para Iphone Manfrotto',1,'',30012662,2170012600,61070000,200000,'SEDE','Operacional','Resolución','MARZO',0,0,200000,0,0,0,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (43,'2025-2600-0945','Alonso Ovalle','Operación Sede','Operación Sede','Adquisición de Equipamiento Audiovisual para eventos de extensión y comunicación','iene como objetivo mejorar la calidad de la producción audiovisual mediante la Adquisición de un micrófono Rode y un trípode Manfrotto, ambos diseñados para su uso con iPhone. El micrófono Rode garantizará una captura de audio clara y profesional en la creación de videos institucionales, mientras que el trípode Manfrotto proporcionará estabilidad y versatilidad durante la filmación. Este equipamiento permitirá optimizar la producción de contenidos, facilitando la creación de videos de alta calidad para campañas de admisión, eventos de extensión y comunicación institucional.','','Adquisición','Equipamiento','Micrófono Rode',1,'',30012662,2170012600,61070000,350000,'SEDE','Operacional','Resolución','MARZO',0,0,350000,0,0,0,0,0,0,0,0,0);
