INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (169,'2025-0100-1448','Casa Central','Dirección General de Admisión, Comunicaciones y Extensión','DGACE','Adquisición de Software - Licencia Capcut pro','Para mejorar la calidad y eficiencia en la creación de contenido para nuestras redes sociales, solicito la Adquisición de una membresía de CapCut, un Osmo Mobile y micrófonos inalámbricos. Estos recursos nos permitirán producir videos más dinámicos, estables y con un audio claro, alineados con los estándares de las principales plataformas digitales.','','Adquisición','Tecnología','Software - Licencia Capcut pro',1,'',Pendiente,100101,61075000,1478014,'SEDE','Corporativo','Resolución','',0,0,0,0,0,1478014,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (175,'2025-0100-1449','Casa Central','Dirección General de Admisión, Comunicaciones y Extensión','DGACE','Adquisición de  Software - Licencia software FIGMA','Figma es una herramienta de diseño y prototipado online que permite que los equipos trabajen juntos en tiempo real. Es fundamental en cualquier proyecto de UX, ya que facilita la creación de interfaces y prototipos interactivos de forma rápida y colaborativa. ¿Cómo nos ayuda? Figma mejora nuestra usabilidad y enfoque en el UX al permitirnos diseñar, probar y ajustar interfaces de usuario en tiempo real. Su plataforma colaborativa nos ayuda a crear experiencias más intuitivas, alineadas con las necesidades de los usuarios. Esto no solo acelera el proceso de diseño, sino que también asegura que las soluciones finales sean más funcionales y efectivas, optimizando la experiencia del usuario desde el principio.','','Adquisición','Tecnología','Software - Licencia software FIGMA',4,'',Pendiente,100101,61075000,709920,'SEDE','Corporativo','Resolución','',0,0,0,0,0,709920,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (176,'2025-0100-1449','Casa Central','Dirección General de Admisión, Comunicaciones y Extensión','DGACE','Adquisición de  Software - Licencia software Miró','Miro es una herramienta online ideal para crear flujos de trabajo, diagramas y paneles interactivos como card sorting. Es especialmente útil para organizar ideas, diseñar cartas Gantt y planificar proyectos de manera visual. ¿Cómo nos ayuda? Miro nos permite organizar mejor la planificación de proyectos, facilitando la creación de flujos claros y visuales que ayudan a estructurar el trabajo. Además, sus herramientas interactivas son excelentes para realizar tests de usuarios, permitiéndonos obtener feedback valioso de manera rápida y eficiente. Con Miro, podemos colaborar en tiempo real, lo que mejora la comunicación del equipo y asegura que cada etapa del proyecto esté bien planificada y testeada antes de avanzar.','','Adquisición','Tecnología','Software - Licencia software Miró',4,'',Pendiente,100101,61075000,757248,'SEDE','Corporativo','Resolución','',0,0,0,0,0,757248,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (177,'2025-0100-1449','Casa Central','Dirección General de Admisión, Comunicaciones y Extensión','DGACE','Adquisición de  Software - Licencia software Parallels','Parallels es una herramienta que permite ejecutar un entorno Windows en equipos Mac, esencial para acceder a aplicaciones y servicios específicos de Windows como correos electrónicos, SharePoint y algunas páginas web desarrolladas que requieren ese entorno.  ¿Cómo nos ayuda? Con Parallels, podemos trabajar sin problemas entre sistemas operativos, lo que nos facilita acceder a herramientas y plataformas que solo funcionan en Windows. Esto nos permite ver y gestionar correos electrónicos, compartir archivos en SharePoint, y visualizar correctamente páginas web desarrolladas para este entorno, asegurando una mayor compatibilidad y eficiencia en nuestras tareas diarias.','','Adquisición','Tecnología','Software - Licencia software Parallels',4,'',Pendiente,100101,61075000,394360,'SEDE','Corporativo','Resolución','',0,0,0,0,0,394360,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (178,'2025-0100-1449','Casa Central','Dirección General de Admisión, Comunicaciones y Extensión','DGACE','Adquisición de  Software - Licencia software Similarweb','Permite analizar el panorama de la competencia, obtener información sobre las palabras claves, fuentes de tráfico y ajustar estrategias relacionadas a la busqueda y selecciones paginas digitales, perfil de visitas, ranking, temas, etc. Identificar oportunidades con datos del mercado y tendencias ','','Adquisición','Tecnología','Software - Licencia software Similarweb',1,'',Pendiente,100101,61075000,3940056,'SEDE','Corporativo','Resolución','',0,0,0,0,0,3940056,0,0,0,0,0,0);
