INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (444,'2025-0700-1049','Liceo Renca','Operación Sede','Electrónica','Adquisición de Sistemas de Citofonía Domiciliaria en Laboratorio 1 - Electrónica','Este proyecto implica la Adquisición de sistemas de citofonía domiciliaria de alta calidad, la selección de proveedores confiables y la implementación de un plan de instalación eficiente. Los sistemas de citofonía seleccionados serán compatibles con diversos tipos de accesos, ofreciendo soluciones tanto para viviendas individuales como para complejos residenciales. Además, se contempla la creación de programas educativos para que los estudiantes comprendan y aprovechen las ventajas de la tecnología de automatización.','','Adquisición','Equipamiento','KIT CITOFONO AUDIO CON AURICULAR 4HILOS 31511102 Bticino',8,'',30012392,160710104,61070000,4020943,'SEDE','Disciplinar','Resolución','MARZO',0,0,4020943,0,0,0,0,0,0,0,0,0);
