INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (821,'2025-1300-1174','Puente Alto','Escuela de Ingeniería, Medio Ambiente y Recursos Naturales','Ingeniería en Medio Ambiente, Ingeniería en Agrícola, Técnico en Geología y Control de Sondaje, Técnico en Geología y Técnico Agrícola.','Adquisición de Equipamiento para Laboratorios de RRNN','Renovación de estación GNSS. La estación móvil D-RTK 2 es compatible con las señales GPS, GLONASS, Beidou y GALILEO. La configuración de la estación móvil D-RTK 2 proporciona datos diferenciales en tiempo real para que los drones logren una precisión de posicionamiento de centímetro. El equipo es compatible con los equipos existentes en Sede.','','Adquisición','Equipamiento','GNSS DJI D-RTK 2 De Alta Precisión',2,'',30012486,1613105,61070000,9496200,'SEDE','Disciplinar','Resolución','ABRIL',0,0,0,9496200,0,0,0,0,0,0,0,0);
