INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (1251,'2025-0400-1363','Valparaíso','Operación Sede','Desarrollo estudiantil','Adquisición de mobiliario para sala multiuso','Equipar Sala Multisusos con mobiliario propio, modular y flexible, para potenciar su caracter adaptativo. El objetivo es ampliar la versatilidad del espacio, permitiendo ajustar y personalizar transitoriamente su configuración de acuerdo con las necesidades específicas de los usuarios y el contexto de cada actividad. Además, de optimizar los esfuerzos operacionales en el acondicionamiento previo a cada evento.','','Adquisición','Mobiliario','1) Pizarra móvil, 2) Gradas modulares, 3) Taburetes, 4) Mesas bajas',2,'',30012282,160476,61070000,4200000,'SEDE','Operacional','Resolución','JUNIO',0,0,0,0,0,4200000,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (1252,'2025-0400-1364','Valparaíso','Operación Sede','Desarrollo estudiantil','Mejoramiento de espacio de estar alummnos','Reacondicionar espacio de estar para alumnos para dar una mejor experiencia y uso a los espacios destinados a los estudiantes. Esto es un tema crítico para la sede dado la falta de ellos','','Mejoramiento','Infraestructura','Implementación total del Proyecto.',1,'',30012283,160476,61080000,78600000,'SEDE','Operacional','Resolución','JUNIO',0,0,0,0,0,78600000,0,0,0,0,0,0);
