INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (1257,'2025-0400-1369','Valparaíso','Operación Sede','SDEG','Mejoramiento de piso CTI','Realizar retiro de cerámicas y porcelanatos, posteriormente hacer tratamiento de “desangrase” al piso, a continuación, se debe alisar el cemento y para finalizar se debe pintar con epóxico de alta densidad (tipo hospital). El proyecto completo e de 800 metros cuadrados y corresponde a Mecánica Automotriz y Maquinaria pesada. Al ser una solicitud de Dirección de Cumplimiento, no tengo claro si es necesario cambiar el piso del segundo piso. - Estandarizar piso taller','Obra de Verano','Mejoramiento','Infraestructura','Piso CTI',1,'',50005114,1604192,61080000,61241700,'DSI','Operacional','Resolución','',0,-4400000,0,0,0,61241700,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (1258,'2025-0400-1370','Valparaíso','Operación Sede','SDEG','Mejoramiento agua, suelo salas VPB1-108 y 109','Desarrollar proyecto 1) Reparación de cerámicos VP108, 2) Cambio llaves de agua V109 y sala Microbiología, 3) Implementación de agua caliente en sala de microbiología, 4) Instalación de conexiones para lavadora (agua y desagüe) y 5)Implementar sistema de apagado de extracción en VP,','','Mejoramiento','Infraestructura','Taller 108 y 109 B1',1,'',30012287,1604192,61080000,62582200,'SEDE','Operacional','Resolución','AGOSTO',0,0,0,0,0,0,0,62582200,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (1259,'2025-0400-1371','Valparaíso','Operación Sede','SDEG','Mejoramiento de aislación y ventilación de segundo piso CTI','Mejoras en el segundo piso del CTI al estar más cerca del techo no hay aislación por lo que la temperatura es muy alta, llegando a 40 grados en verano; adicionalmente se concentran los gases de escape de los autos, lo que afecta la calidad del aire - Mejoramiento ventilación y salida de gases','Obra de Verano','Mejoramiento','Infraestructura','Mejoramiento altillo CTI',1,'',50005115,1604192,61080000,9558512,'DSI','Operacional','Resolución','',0,0,0,0,0,9558512,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (1260,'2025-0400-1372','Valparaíso','Operación Sede','SDEG','Mejoramiento iluminacion -1 CTI','Cambio de Iluminación de acuerdo Normativa Eléctrica vigente en Laboratorios planta baja CTI.','','Mejoramiento','Infraestructura','Iluminación -1 CTI',1,'',30012288,1604192,61080000,21984578,'SEDE','Operacional','Resolución','ABRIL',0,0,0,21984578,0,0,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (1261,'2025-0400-1373','Valparaíso','Operación Sede','SDEG','Mejoramiento inyección de aire CTI','Se debe mejorar el sistema de inyección de aire en laboratorios -1 CTI. Estos se encuentran fuera de funcionamiento y el interruptor general dentro de un tablero eléctrico ubicado al final del pasillo. El sistema de extracción funciona, pero los gases son inyectados al pasillo en donde se encuentran otros laboratorios o alumnos en su hora de descanso.','Obra de Verano','Mejoramiento','Infraestructura','Extracción aire -1 CTI',1,'',50005116,1604192,61080000,13381917,'DSI','Operacional','Resolución','',0,0,0,0,0,13381917,0,0,0,0,0,0);
INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (1262,'2025-0400-1374','Valparaíso','Operación Sede','SDEG','Mejoramiento en techo sala multiuso','Se debe mejorar el sistema de inyección de aire en laboratorios anteriormente descritos. Estos se encuentran fuera de funcionamiento y el interruptor general dentro de un tablero eléctrico ubicado al final del pasillo. El sistema de extracción funciona, pero los gases son inyectados al pasillo en donde se encuentran otros laboratorios o alumnos en su hora de descanso.','Obra de Verano','Mejoramiento','Infraestructura','Techado terraza 1 piso B1',1,'',50005117,1604192,61080000,33454793,'DSI','Operacional','Resolución','',0,4400000,0,0,0,33454793,0,0,0,0,0,0);
