"INSERT INTO [Subdireccion de Proyectos BBDD].[dbo].[Matriz_CAPEX_Regular] VALUES (704,'2025-1100-1150','Plaza Vespucio','Operación Sede','Operación Sede','Habilitación de oficina de Coordinacion de Servicios Generales','De acuerdo a solicitud de Área Académica Sede SDA, la actual Coordinación de SSGG que se ubica en oficina de Coordinaciones de piso 2 de Boulevard (recientemente habilitada con CAPEX 2024 operacional) debe quedar exclusivamente habilitada para Coordinaciones de carrera debido a los temas privados que muchas veces exponen los estudiantes hacia sus áreas académicas.-
